tool_input.command:
$f='D:\repository\门户\zhi2-web-admin-wt-payfund\src\views\property\marketMonitor\assets\data.raw.js'
$j = Get-Content $f -Raw
# Show each payFull occurrence with context to design payFund values
[regex]::Matches($j,'"month":"(\d+)","localSuzhou":\d+,"nonSuzhou":\d+,"ageUnder30":\d+,"age30To45":\d+,"age45To60":\d+,"ageOver60":\d+,"payFull":(\d+),"payInstallment":(\d+),"payMortgage":(\d+)') | ForEach-Object {
  [pscustomobject]@{month=$_.Groups[1].Value; full=[int]$_.Groups[2].Value; inst=[int]$_.Groups[3].Value; mort=[int]$_.Groups[4].Value}
} | Format-Table -AutoSize

$f='D:\repository\门户\zhi2-web-admin-wt-payfund\src\views\property\marketMonitor\assets\data.raw.js'
$j = Get-Content $f -Raw
# payFund per month (mortgage * ~0.30, rounded to nearest 10)
$funds = @{
 '202512'=720;'202601'=520;'202602'=320;'202603'=820;'202604'=980;'202605'=960;
 '202606'=1050;'202607'=940;'202608'=680;'202609'=830;'202610'=1020;'202611'=790
}
$count = 0
foreach($k in $funds.Keys){
  $pat = '("month":"'+$k+'".*?"payMortgage":(\d+))'
  $new = $j -replace $pat, ('$1,"payFund":'+$funds[$k])
  if($new -ne $j){ $count++ ; $j = $new }
}
Set-Content -Path $f -Value $j -NoNewline -Encoding UTF8
Write-Output "months updated: $count"
